function outputs=plot_q6_procedure_subject001_design_fit(hb_label,channel_id)
% Q6 Procedure subject001: HRF, regressor heatmap/timeseries and fit.
if nargin<1,hb_label="HbO";end;if nargin<2,channel_id=1;end;hb_label=string(hb_label);assert(any(hb_label==["HbO","HbR"]));sid='subject001';repo=fileparts(fileparts(fileparts(mfilename('fullpath'))));glm='C:\aliceproject\GLM';fl=fullfile(glm,'first_level');spec=fullfile(repo,'results','q6_extraneous_procedure','cohort_specification',sid,char(hb_label));spm_file=fullfile(spec,sprintf('SPM_indiv_%s.mat',hb_label));assert(isfile(spm_file));out=fullfile(spec,'figures');if ~isfolder(out),mkdir(out);end;addpath(fl);addpath(fullfile(glm,'toolboxes','spm'));addpath(genpath(fullfile(glm,'toolboxes','NIRS_SPM_v4_r1')));L=load(spm_file,'SPM_nirs');S=L.SPM_nirs;X=full(S.xX.X);N=string(S.xX.name(:));task=~contains(lower(N),'constant');assert(sum(task)==4);
set(0,'DefaultFigureVisible','off');h=(0:size(S.xBF.bf,1)-1)'*double(S.xBF.dt);f=figure('Color','w','Position',[100 100 1000 520]);set(f,'DefaultAxesColor','w','DefaultAxesXColor','k','DefaultAxesYColor','k','DefaultTextColor','k');plot(h,S.xBF.bf(:,1),'Color',[0 0.35 0.7],'LineWidth',1.8);grid on;xlabel('Time after event onset (s)');ylabel('HRF amplitude');title(sprintf('Q6 Procedure canonical HRF (%s)',hb_label),'Color','k');hrf=fullfile(out,sprintf('%s_%s_q6_procedure_canonical_hrf.png',sid,hb_label));exportgraphics(f,hrf,'Resolution',220);close(f);
f=figure('Color','w','Position',[100 100 1350 520]);set(f,'DefaultAxesColor','w','DefaultAxesXColor','k','DefaultAxesYColor','k','DefaultTextColor','k');imagesc(X(:,task)');axis tight;colormap(f,parula);cb=colorbar;cb.Color='k';yticks(1:4);yticklabels(N(task));xlabel('Scan');ylabel('HRF-convolved task regressor');title(sprintf('%s Q6 Procedure: regressor heatmap (%s)',sid,hb_label),'Color','k');heat=fullfile(out,sprintf('%s_%s_q6_procedure_convolved_regressor_heatmap.png',sid,hb_label));exportgraphics(f,heat,'Resolution',220);close(f);
rt=double(S.xY.RT);t=(0:size(X,1)-1)'*rt;f=figure('Color','w','Position',[100 100 1500 600]);set(f,'DefaultAxesColor','w','DefaultAxesXColor','k','DefaultAxesYColor','k','DefaultTextColor','k');plot(t,X(:,task),'LineWidth',1.1);grid on;xlabel('Time (s)');ylabel('Task regressor');title(sprintf('%s Q6 Procedure: four HRF-convolved regressors (%s)',sid,hb_label),'Color','k');legend(N(task),'Location','eastoutside');ts=fullfile(out,sprintf('%s_%s_q6_procedure_convolved_regressor_timeseries.png',sid,hb_label));exportgraphics(f,ts,'Resolution',220);close(f);
if ~isfield(S.nirs,'beta')||~isfield(S.xX,'xKXs'),outputs=struct('hrf_png',hrf,'heatmap_png',heat,'timeseries_png',ts,'fit_png',"");return;end;if hb_label=="HbO",field='oxyData';else,field='dxyData';end;data=load(fullfile(fl,'nirs_spm_inputs_v2_fulltimeline_trial1',sid,[sid '_nirs_data.mat']),'nirs_data');y=double(data.nirs_data.(field)(:,channel_id));yf=spm_filter_HPF_LPF_WMDL(S.xX.K,y);Xf=full(S.xX.xKXs.X);b=double(S.nirs.beta(:,channel_id));fit=Xf*b;res=yf-fit;f=figure('Color','w','Position',[100 100 1550 900]);set(f,'DefaultAxesColor','w','DefaultAxesXColor','k','DefaultAxesYColor','k','DefaultTextColor','k');tiledlayout(3,1,'TileSpacing','compact','Padding','compact');nexttile;plot(t,yf,'Color',[0 0.35 0.7]);hold on;plot(t,fit,'Color',[0.85 0.33 0.1],'LineWidth',1.2);grid on;xlabel('Time (s)');ylabel('Filtered concentration');title(sprintf('%s channel %d %s: observed and fitted signal',sid,channel_id,hb_label),'Color','k');legend({'Observed','GLM fitted'},'Location','eastoutside');nexttile;plot(t,res,'Color',[0 0.35 0.7]);hold on;yline(0,'--k');grid on;xlabel('Time (s)');ylabel('Residual');title('GLM residual','Color','k');nexttile;plot(t,X(:,task),'LineWidth',1);grid on;xlabel('Time (s)');ylabel('Regressor');title('Q6 Procedure HRF-convolved task regressors','Color','k');legend(N(task),'Location','eastoutside');fp=fullfile(out,sprintf('%s_channel%02d_%s_q6_procedure_fit.png',sid,channel_id,hb_label));exportgraphics(f,fp,'Resolution',220);close(f);outputs=struct('hrf_png',hrf,'heatmap_png',heat,'timeseries_png',ts,'fit_png',fp);
end
